const crypto = require('crypto');
const b = $json.body || $json;
const command = { environment: b.environment, operation: b.operation, table: b.table, target_filter: b.target_filter, values: b.values, expected_rows: b.expected_rows };
const command_json = JSON.stringify(command);
const command_sha256 = crypto.createHash('sha256').update(command_json).digest('hex');
return [{ json: { request_id: b.request_id, approver: b.approver, command, command_json, command_sha256, before_after_summary: b.before_after_summary || 'Review the proposed field changes', callback_url: b.callback_url || 'https://YOUR-N8N/webhook/shsy-ai-database-change-result', timeout_minutes: b.timeout_minutes || 60 } }];

const crypto = require('crypto');
const c = $json.context || {};
const freshHash = crypto.createHash('sha256').update(c.command_json || '').digest('hex');
return [{ json: { ...$json, authorized: $json.status === 'approved' && freshHash === c.command_sha256, command: JSON.parse(c.command_json || '{}') } }];
